import{_ as o,o as t,c as a,a6 as r}from"./chunks/framework.DtfPIzdJ.js";const u=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md"}'),s={name:"glossary.md"};function n(d,e,c,i,l,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Every term used in the Cluub language, CLI and docs, in alphabetical order. Each entry links to the page that covers it in depth.</p><h2 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A&quot;">​</a></h2><p><strong>about</strong>: A one-line description on an app, model, store, service, api, page, component or action: <code>about &quot;Place a new order&quot;</code>. It powers <code>cluub explain</code>, and Cluub suggests adding it when a service, api or page has none (W104). See <a href="/home/guide/team">POs, BAs, QAs &amp; AI</a>.</p><p><strong>action</strong>: A named piece of behavior. In a <strong>service</strong>, an action is business logic (<code>action add(title: text) -&gt; Todo</code>). In a <strong>page</strong>, an action is what happens when the user does something, and it may change state and call apis. As a component property type (<code>onRemove: action</code>), it&#39;s a callback the page passes in. See <a href="/home/guide/backend">Services &amp; APIs</a>.</p><p><strong>api</strong>: A declaration in <code>api/</code> that exposes service actions as HTTP routes: <code>api TodoApi at &quot;/api/todos&quot;</code>. Apis may only use services (layer rule). Their parameters are validated before your code runs. See <a href="/home/guide/backend">Services &amp; APIs</a> and the <a href="/home/reference/api">api reference</a>.</p><p><strong>app</strong>: The single declaration in <code>app.clb</code> that names the project (PascalCase) and holds the settings <code>about</code>, <code>port</code>, <code>ai</code>, <code>aiModel</code> and <code>lang</code>. An unknown setting is warning W108, and a second <code>app</code> is error E101.</p><p><strong>ask ai</strong>: The expression that calls a language model: <code>ask ai &quot;Summarize {text}&quot;</code>. It can be followed by <code>as Model</code>, <code>as one of [...]</code>, <code>using &quot;provider&quot;</code> and <code>with system &quot;...&quot;</code>. It&#39;s only allowed in the backend (E204). See <a href="/home/guide/ai">AI</a>.</p><p><strong>as Model / as one of</strong>: Modifiers on <code>ask ai</code> that make the reply structured. <code>as Contact</code> parses the reply as JSON and validates it against the model, retrying once. <code>as one of [&quot;bug&quot;, &quot;feature&quot;]</code> always returns exactly one of the options.</p><h2 id="b" tabindex="-1">B <a class="header-anchor" href="#b" aria-label="Permalink to &quot;B&quot;">​</a></h2><p><strong>backend</strong>: The server half of an app: models, stores, clients, services and apis, compiled into <code>dist/server.js</code>.</p><p><strong>build</strong>: <code>cluub build</code> compiles the project into <code>dist/</code>, which <code>cluub start</code> or <code>node dist/start.mjs</code> runs. It fails with exit code 1 on any error. See <a href="/home/guide/deployment">Deployment</a>.</p><p><strong>built-in</strong>: A function or value that&#39;s always available: <code>now()</code>, <code>today()</code>, <code>round()</code>, <code>text()</code>, <code>number()</code>, <code>uuid()</code>, <code>json()</code>, <code>random()</code>, <code>sleep()</code>, <code>env</code> (backend only) and <code>screen</code> (tests only).</p><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><p><strong>check</strong>: <code>cluub check</code> reports errors, warnings and suggestions without building anything. It exits with code 1 on errors.</p><p><strong>client</strong>: A declaration in <code>network/</code> that describes an outside HTTP API, with a base URL, headers and typed routes. It belongs to the <strong>network layer</strong>, and services use it. In tests, client calls return <code>nothing</code>. See the <a href="/home/reference/client">client reference</a>.</p><p><strong>component</strong>: A reusable, stateless piece of UI in <code>ui/components/</code>. It receives data with <code>takes</code>, has a <code>view</code>, and may not <code>uses</code> anything (E203). It&#39;s used from a page as <code>TodoItem todo: t, onRemove: remove</code>. See <a href="/home/guide/frontend">Pages &amp; components</a>.</p><p><strong>crash message</strong>: The text <code>This page hit an error while drawing: …</code> that the runtime shows in place of a page whose view threw an error. See <a href="/home/guide/troubleshooting">Troubleshooting</a>.</p><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h2><p><strong>declaration</strong>: A top-level building block of a Cluub file: <code>app</code>, <code>model</code>, <code>store</code>, <code>client</code>, <code>service</code>, <code>api</code>, <code>page</code>, <code>component</code>, <code>layout</code> or <code>test</code>. Each kind lives in its own folder (E301), and names are PascalCase (E102).</p><p><strong>dependency injection</strong>: Cluub builds each service and api with exactly the dependencies listed in its <code>uses</code> line. Tests get the same wiring with empty in-memory stores and a fake AI. See <a href="/home/guide/structure">Project structure &amp; layers</a>.</p><p><strong>diagnostic</strong>: Any problem the compiler reports. It carries a code, a file, a line and a column, a message and usually a hint. Diagnostics come in three severities: <strong>error</strong> (<code>E…</code>, blocks the build), <strong>warning</strong> (<code>W…</code>) and <strong>suggestion</strong>. See <a href="/home/guide/errors">Errors &amp; suggestions</a>.</p><p><strong>dist</strong>: The output folder written by <code>cluub build</code> and <code>cluub dev</code>. It&#39;s standalone: <code>node dist/start.mjs</code> runs it with plain Node.js. It&#39;s deleted and rewritten on every build.</p><h2 id="e" tabindex="-1">E <a class="header-anchor" href="#e" aria-label="Permalink to &quot;E&quot;">​</a></h2><p><strong>env</strong>: The backend-only built-in that reads configuration: <code>env.STRIPE_KEY</code>. Values come from the process environment and <code>.env</code> (real environment variables win over <code>.env</code>). Reading <code>env</code> in the UI is E205.</p><p><strong>error code</strong>: The identifier of a diagnostic, such as E201 or W104. Look one up with <code>cluub errors E201</code> or in the <a href="/home/reference/errors">error reference</a>.</p><p><strong>event</strong>: A user interaction bound to an action in a view: <code>on click</code>, <code>on change</code>, <code>on input</code>, <code>on enter</code>, <code>on submit</code>, <code>on blur</code>, <code>on focus</code>. The handler must call an action (E113). See <a href="/home/reference/properties-events">Properties &amp; events</a>.</p><p><strong>explain</strong>: <code>cluub explain [--for po|ba|qa|dev]</code> writes a plain-English Markdown overview of the project straight from the code. See <a href="/home/guide/team">POs, BAs, QAs &amp; AI</a>.</p><h2 id="f" tabindex="-1">F <a class="header-anchor" href="#f" aria-label="Permalink to &quot;F&quot;">​</a></h2><p><strong>fail</strong>: The statement that stops an action with an error: <code>fail &quot;Free accounts can order up to 500&quot; status 403</code>. The default status is 400.</p><p><strong>fake AI</strong>: The stand-in for <code>ask ai</code> used by every test. It returns <code>AI reply to: &lt;prompt start&gt;</code> for text, a valid sample for <code>as Model</code>, an empty list for <code>as list of</code>, and the first option for <code>as one of</code>. It never touches the network. See <a href="/home/guide/testing-strategy#fake-ai-and-the-no-network-rule">Testing strategy</a>.</p><p><strong>file store</strong>: A store with <code>saved in &quot;path.json&quot;</code>. It loads when the server starts, keeps every record in memory, and writes the whole JSON file atomically on each change, relative to the project root. See <a href="/home/guide/deployment#data-file-stores-and-backups">Deployment</a>.</p><h2 id="g" tabindex="-1">G <a class="header-anchor" href="#g" aria-label="Permalink to &quot;G&quot;">​</a></h2><p><strong>generated test</strong>: A test that <code>cluub test</code> writes into <code>tests/generated/</code> from your code: model rules, <code>require</code> checks, api validation, page rendering and button clicks. The files are rewritten on every run, so don&#39;t edit them. See <a href="/home/guide/testing">Automatic tests</a>.</p><p><strong>go to</strong>: The statement that navigates to another page without a reload: <code>go to &quot;/orders&quot;</code>. It&#39;s allowed in pages and tests only.</p><h2 id="h" tabindex="-1">H <a class="header-anchor" href="#h" aria-label="Permalink to &quot;H&quot;">​</a></h2><p><strong>hint</strong>: The &quot;how to fix it&quot; line under a diagnostic, often a &quot;Did you mean …?&quot; suggestion based on spelling distance.</p><p><strong>holds</strong>: The keyword that ties a store to its model: <code>store Todos holds Todo</code>.</p><h2 id="i" tabindex="-1">I <a class="header-anchor" href="#i" aria-label="Permalink to &quot;I&quot;">​</a></h2><p><strong>id</strong>: The optional identifier every model instance has. Stores assign <code>&quot;1&quot;</code>, <code>&quot;2&quot;</code>, … when you add a record without one. It&#39;s always text.</p><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L&quot;">​</a></h2><p><strong>label (property)</strong>: A view property that gives an element an accessible name (<code>aria-label</code>): <code>button &quot;Delete&quot;, label &quot;Delete {todo.title}&quot;</code>. An <code>input</code> or <code>select</code> without it uses its placeholder. Not to be confused with the <code>label</code> view element, which renders a visible <code>&lt;label&gt;</code>. See <a href="/home/guide/accessibility">Accessibility</a>.</p><p><strong>lang</strong>: The <code>app</code> setting that sets the page language (<code>&lt;html lang&gt;</code>), for example <code>lang &quot;de&quot;</code>. The default is <code>en</code>.</p><p><strong>layer</strong>: One of the architectural levels every project follows: <strong>UI</strong> (pages, components, layouts), <strong>api</strong>, <strong>service</strong>, and <strong>data</strong> (stores) or <strong>network</strong> (clients). Models are shared by all of them.</p><p><strong>layer rule</strong>: The enforced direction of dependencies: page → api → service → store, client or service. Breaking it is E201. See <a href="/home/guide/structure">Project structure &amp; layers</a>.</p><p><strong>layout</strong>: A declaration in <code>ui/layouts/</code> that wraps pages with shared UI such as a header and footer. A page opts in with <code>layout Main</code>, and the layout marks where the page goes with exactly one <code>slot</code> (warning W107 otherwise).</p><p><strong>LANGUAGE.md</strong>: The complete language reference in the repository root. <code>cluub make</code> gives it to the AI.</p><p><strong>live reload</strong>: <code>cluub dev</code> rebuilds when a <code>.clb</code>, <code>.css</code> or <code>.env</code> file changes. Each build has an id, and the browser reloads when it sees a new one. See <a href="/home/guide/troubleshooting#live-reload-doesn-t-reload">Troubleshooting</a>.</p><h2 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M&quot;">​</a></h2><p><strong>make</strong>: <code>cluub make &quot;&lt;request&gt;&quot;</code> asks an AI to write or change <code>.clb</code> files and only writes them when the whole project compiles (up to three attempts). See <a href="/home/guide/ai">AI</a>.</p><p><strong>model</strong>: A declaration in <code>models/</code> that describes a data shape and its validation rules: <code>title: text, required, max 80</code>. Creating one (<code>Todo(title: &quot;x&quot;)</code>) validates it. See <a href="/home/guide/data">Models &amp; data</a> and the <a href="/home/reference/model">model reference</a>.</p><p><strong>model rule</strong>: A constraint on a model field: <code>required</code>, <code>min N</code>, <code>max N</code>, <code>one of [...]</code>, each with an optional custom message.</p><h2 id="n" tabindex="-1">N <a class="header-anchor" href="#n" aria-label="Permalink to &quot;N&quot;">​</a></h2><p><strong>nothing</strong>: Cluub&#39;s missing value (like <code>null</code>). Optional types are written <code>T?</code>.</p><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><p><strong>page</strong>: A screen with a URL, in <code>ui/pages/</code>: <code>page Home at &quot;/&quot;</code>. It may have <code>title</code>, <code>layout</code>, <code>uses</code> (apis only), <code>state</code>, <code>when loaded</code>, actions and a <code>view</code>. See <a href="/home/guide/frontend">Pages &amp; components</a> and the <a href="/home/reference/page">page reference</a>.</p><p><strong>path parameter</strong>: A <code>{name}</code> segment in a route or page path, such as <code>&quot;/todos/{id}&quot;</code>. It&#39;s available by name in the route body or page, and is always text.</p><p><strong>playground</strong>: The in-browser editor on the docs site that compiles, runs and tests Cluub code with no install. See <a href="/home/playground">Playground</a>.</p><p><strong>project root</strong>: The folder that contains <code>app.clb</code>. CLI commands search upward for it, and file stores and <code>.env</code> are relative to it.</p><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h2><p><strong>render</strong>: In a test, <code>render Home</code> opens a page headlessly against a fresh in-memory backend.</p><p><strong>request</strong>: In a test, <code>request post &quot;/api/todos&quot; with {title: &quot;x&quot;}</code> calls an api route and gives back <code>status</code> and <code>body</code>.</p><p><strong>require</strong>: The statement that guards an action: <code>require total &gt; 0, &quot;Total must be positive&quot;</code>. If the condition is false, the action fails with status 400 and that message, and the test generator writes a test that breaks it.</p><p><strong>route</strong>: One HTTP endpoint inside an api or client: method (<code>get</code>, <code>post</code>, <code>put</code>, <code>patch</code>, <code>delete</code>), name, path and <code>with</code> parameters. Parameters come from the path, the query string (get/delete) or the JSON body.</p><p><strong>runtime</strong>: The JavaScript in <code>runtime/</code> that runs compiled programs: models, stores, the api dispatcher, the virtual DOM, the router, AI providers and the test runner. It has zero dependencies.</p><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><p><strong>screen</strong>: In a test, all visible text of the rendered page, including input values and the current toast: <code>expect screen has &quot;Saved&quot;</code>.</p><p><strong>service</strong>: A declaration in <code>services/</code> that holds business logic and AI calls. It <code>uses</code> stores, clients and other services (but not in a circle, E202). See <a href="/home/guide/backend">Services &amp; APIs</a>.</p><p><strong>slot</strong>: The view line in a layout that marks where the page&#39;s content goes. Using it outside a layout is E013.</p><p><strong>state</strong>: Data owned by a page that the view displays: <code>state draft = &quot;&quot;</code>. Assigning to it re-renders the page. Inputs bind to state (E112).</p><p><strong>store</strong>: A declaration in <code>data/</code> that keeps records of one model, in memory or in a JSON file. Methods: <code>all</code>, <code>find</code>, <code>get</code>, <code>add</code>, <code>update</code>, <code>remove</code>, <code>where</code>, <code>count</code>, <code>clear</code>. It belongs to the <strong>data layer</strong>. See the <a href="/home/reference/store">store reference</a>.</p><p><strong>style</strong>: A view property that applies a theme variant: <code>style primary | danger | ghost | muted</code>.</p><p><strong>suggestion</strong>: The mildest diagnostic. It teaches a good habit (such as adding <code>about</code>) and never blocks anything.</p><h2 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h2><p><strong>takes</strong>: The line where a component declares the properties it receives: <code>takes todo: Todo, onRemove: action</code>. Missing or unknown properties are E114.</p><p><strong>template</strong>: A starter project for <code>cluub new --template app | ai-chat | blank</code>.</p><p><strong>test</strong>: A declaration in <code>tests/</code> with a name and statements such as <code>expect</code>, <code>render</code>, <code>type … into</code>, <code>click</code> and <code>request</code>. See <a href="/home/guide/testing">Automatic tests</a>.</p><p><strong>theme.css</strong>: The built-in stylesheet (<code>/_cluub/theme.css</code>), or your override file in the project root, served as <code>/assets/theme.css</code>.</p><p><strong>toast</strong>: The message box the runtime shows at the bottom of the page when an action fails. It&#39;s announced to screen readers (<code>role=&quot;alert&quot;</code>) and disappears after 5 seconds.</p><h2 id="u" tabindex="-1">U <a class="header-anchor" href="#u" aria-label="Permalink to &quot;U&quot;">​</a></h2><p><strong>uses</strong>: The line that declares a declaration&#39;s dependencies: <code>uses Todos, Mailer</code>. Using an undeclared dependency is E106, and declaring an unused one is W101.</p><p><strong>using</strong>: The <code>ask ai</code> modifier that picks a provider or model for one call: <code>using &quot;ollama:llama3.2&quot;</code>.</p><h2 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to &quot;V&quot;">​</a></h2><p><strong>view</strong>: The block that describes what a page, component or layout shows, made of view elements, components, <code>for</code> and <code>if</code>. A view only shows data: calling an api, an action or <code>sleep()</code> while it draws is E117. See <a href="/home/reference/view-elements">View elements</a>.</p><p><strong>view element</strong>: A built-in UI building block such as <code>heading</code>, <code>text</code>, <code>button</code>, <code>input</code>, <code>row</code>, <code>card</code> or <code>list</code>. An unknown element is E013.</p><p><strong>virtual DOM</strong>: The runtime&#39;s in-memory description of the page. After each change it is rebuilt and compared with the previous one, and only the differences are applied to the browser&#39;s DOM. See <a href="/home/guide/performance#the-runtime-model">Performance</a>.</p><h2 id="w" tabindex="-1">W <a class="header-anchor" href="#w" aria-label="Permalink to &quot;W&quot;">​</a></h2><p><strong>warning</strong>: A diagnostic (<code>W101</code>–<code>W108</code>) for code that works but will hurt later, such as an unused dependency or an oversized action. Warnings don&#39;t block the build.</p><p><strong>when loaded</strong>: The page block that runs when the page opens, typically to fetch data.</p><p><strong>with</strong>: In a route, it introduces the parameters: <code>post add at &quot;/&quot; with title: text</code>. In <code>ask ai</code>, <code>with system &quot;...&quot;</code> sets the system prompt. In tests, <code>request post &quot;/x&quot; with {...}</code> sets the body.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/home/faq">FAQ</a></li><li><a href="/home/reference/language">Language reference</a></li><li><a href="/home/reference/errors">Error codes</a></li><li><a href="/home/guide/introduction">Why Cluub</a></li></ul>',92)])])}const g=o(s,[["render",n]]);export{u as __pageData,g as default};
